import React from 'react';

interface AppleIconProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  name:
    | 'dollarsign.gauge.chart.leftthird.topthird.rightthird'
    | 'shippingbox'
    | 'person.2'
    | 'creditcard'
    | 'calendar.badge.clock'
    | 'truck.box'
    | 'receipt'
    | 'qrcode'
    | 'square.stack.3d.up'
    | 'mappin.and.ellipse'
    | 'whatsapp'
    | 'checkmark.seal'
    | 'person.badge.plus'
    | 'person.text.rectangle'
    | 'storefront'
    | 'calendar'
    | 'location.magnifyingglass'
    | 'tag';
  size?: number | string;
  className?: string;
  alt?: string;
}

export const AppleIcon: React.FC<AppleIconProps> = ({
  name,
  size = 20,
  className = '',
  alt = '',
  style,
  ...props
}) => {
  const pixelSize = typeof size === 'number' ? `${size}px` : size;

  return (
    <img
      src={`/icons/${name}.svg`}
      alt={alt || name}
      className={`inline-block shrink-0 select-none object-contain ${className}`}
      style={{
        width: pixelSize,
        height: pixelSize,
        ...style,
      }}
      loading="eager"
      draggable={false}
      {...props}
    />
  );
};

